package br.com.joaovictor.meuritmolite;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.time.*;import java.util.*;
public final class Scheduler {
 static final String PREF="rhythm_alarms",CHANNEL="ritmo_alarms_v1",REMINDERS="ritmo_reminders_v1";
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences(PREF,Context.MODE_PRIVATE);}
 static AlarmManager manager(Context c){return (AlarmManager)c.getSystemService(Context.ALARM_SERVICE);}
 static boolean exact(Context c){return Build.VERSION.SDK_INT<31||manager(c).canScheduleExactAlarms();}
 static boolean notifications(Context c){return ((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled();}
 static void channels(Context c){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel a=new NotificationChannel(CHANNEL,"Alarmes sonoros",NotificationManager.IMPORTANCE_HIGH);a.setDescription("Alarmes individuais com som e ações de parar e adiar.");a.enableVibration(true);a.setSound(null,null);n.createNotificationChannel(a);NotificationChannel r=new NotificationChannel(REMINDERS,"Lembretes",NotificationManager.IMPORTANCE_DEFAULT);r.setDescription("Avisos sem alarme sonoro contínuo.");n.createNotificationChannel(r);}
 static PendingIntent pending(Context c,String id,long at,String title,boolean sound,String action){Intent i=new Intent(c,AlarmReceiver.class).setAction(action).setData(android.net.Uri.parse("ritmo://alarm/"+android.net.Uri.encode(id))).putExtra("id",id).putExtra("at",at).putExtra("title",title).putExtra("sound",sound);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static boolean schedule(Context c,String id,long at,String title,boolean sound){if(!exact(c)||!notifications(c))return false;PendingIntent show=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);manager(c).setAlarmClock(new AlarmManager.AlarmClockInfo(at,show),pending(c,id,at,title,sound,"FIRE"));return true;}
 static void cancel(Context c,String id){RingingService.dismissIfRunning(id);manager(c).cancel(pending(c,id,0,"",false,"FIRE"));manager(c).cancel(pending(c,id+"#snooze",0,"",false,"FIRE"));prefs(c).edit().remove("snooze:"+id).remove("dismissed:"+id).apply();}
 static Set<String> strings(JSONArray a){Set<String>s=new HashSet<>();if(a!=null)for(int i=0;i<a.length();i++)s.add(a.optString(i));return s;}
 static JSONObject compact(JSONObject i)throws JSONException{JSONObject o=new JSONObject();for(String k:new String[]{"id","title","type","date","time","repeat","days","skip","completed","archived","enabled","notify","soundAlarm"})if(i.has(k))o.put(k,i.get(k));return o;}

 static boolean onlyMirroredDismissal(Context c,String id,JSONObject current,JSONObject previous)throws JSONException{String day=prefs(c).getString("dismissed:"+id,"");if(day.isEmpty())return false;Set<String>now=strings(current.optJSONArray("completed")),before=strings(previous.optJSONArray("completed"));if(!now.contains(day))return false;now.remove(day);before.remove(day);if(!now.equals(before))return false;JSONObject a=new JSONObject(current.toString()),b=new JSONObject(previous.toString());a.remove("completed");b.remove("completed");return a.toString().equals(b.toString());}
 public static synchronized void sync(Context c,String raw)throws JSONException{JSONObject d=new JSONObject(raw);JSONArray items=d.getJSONArray("items");if(items.length()>2000||raw.length()>2000000)throw new JSONException("limit");JSONArray list=new JSONArray();Set<String>ids=new HashSet<>();for(int j=0;j<items.length();j++){JSONObject i=items.getJSONObject(j);String type=i.optString("type");boolean wanted=type.equals("alarm")||type.equals("reminder")||i.optBoolean("notify");if(!wanted||i.optBoolean("archived")||!i.optBoolean("enabled",true)||i.optString("time").isEmpty())continue;String id=i.getString("id"),title=i.getString("title");if(id.length()>80||title.length()>160||ids.contains(id))throw new JSONException("invalid");LocalDate.parse(i.getString("date"));LocalTime.parse(i.getString("time"));ids.add(id);list.put(compact(i));}
  if(list.length()>200)throw new JSONException("Limite de 200 avisos ativos.");
  JSONArray old=new JSONArray(prefs(c).getString("items","[]"));for(int j=0;j<old.length();j++){String id=old.getJSONObject(j).getString("id");if(!ids.contains(id))cancel(c,id);}
  for(int j=0;j<list.length();j++){JSONObject current=list.getJSONObject(j);String id=current.getString("id");for(int k=0;k<old.length();k++){JSONObject previous=old.getJSONObject(k);if(id.equals(previous.optString("id"))&&!current.toString().equals(previous.toString())&&!onlyMirroredDismissal(c,id,current,previous)){cancel(c,id);prefs(c).edit().remove("last:"+id).apply();break;}}}
  prefs(c).edit().putString("items",list.toString()).commit();reschedule(c);
 }
 public static synchronized void reschedule(Context c){channels(c);try{JSONArray list=new JSONArray(prefs(c).getString("items","[]"));JSONArray scheduled=new JSONArray();for(int j=0;j<list.length();j++){JSONObject i=list.getJSONObject(j);String id=i.getString("id");manager(c).cancel(pending(c,id,0,"",false,"FIRE"));long now=System.currentTimeMillis();Set<Integer>days=new HashSet<>();JSONArray a=i.optJSONArray("days");if(a!=null)for(int k=0;k<a.length();k++)days.add(a.getInt(k));Set<String>skip=strings(i.optJSONArray("skip"));skip.addAll(strings(i.optJSONArray("completed")));if(prefs(c).contains("dismissed:"+id))skip.add(prefs(c).getString("dismissed:"+id,""));long next=Occurrence.next(LocalDate.parse(i.getString("date")),LocalTime.parse(i.getString("time")),i.optString("repeat","none"),days,skip,now,prefs(c).getLong("last:"+id,0),ZoneId.systemDefault());boolean sound=i.optString("type").equals("alarm")||i.optBoolean("soundAlarm");if(next>0&&schedule(c,id,next,i.getString("title"),sound))scheduled.put(new JSONObject().put("id",id).put("at",next).put("sound",sound));long snooze=prefs(c).getLong("snooze:"+id,0);if(snooze>now)schedule(c,id+"#snooze",snooze,i.getString("title"),sound);else prefs(c).edit().remove("snooze:"+id).apply();}prefs(c).edit().putString("scheduled",scheduled.toString()).apply();}catch(Exception ignored){prefs(c).edit().putString("scheduled","[]").apply();}}
 static boolean soundFor(Context c,String id){try{JSONArray a=new JSONArray(prefs(c).getString("items","[]"));for(int n=0;n<a.length();n++){JSONObject i=a.getJSONObject(n);if(id.equals(i.optString("id")))return "alarm".equals(i.optString("type"))||i.optBoolean("soundAlarm");}}catch(Exception ignored){}return false;}
 static boolean exists(Context c,String id){try{JSONArray a=new JSONArray(prefs(c).getString("items","[]"));for(int n=0;n<a.length();n++)if(id.equals(a.getJSONObject(n).optString("id")))return true;}catch(Exception ignored){}return false;}
 static String base(String id){return id.endsWith("#snooze")?id.substring(0,id.length()-7):id;}
 static void dismissed(Context c,String id,boolean snooze,String title,boolean sound){String base=base(id);manager(c).cancel(pending(c,base+"#snooze",0,"",false,"FIRE"));prefs(c).edit().putString("dismissed:"+base,LocalDate.now().toString()).remove("snooze:"+base).commit();if(snooze&&exists(c,base)){long at=System.currentTimeMillis()+10*60000;prefs(c).edit().putLong("snooze:"+base,at).apply();schedule(c,base+"#snooze",at,title,sound);}reschedule(c);}
 static JSONObject status(Context c){JSONObject o=new JSONObject();try{o.put("exact",exact(c)).put("notifications",notifications(c)).put("scheduled",new JSONArray(prefs(c).getString("scheduled","[]"))).put("active",RingingService.activeSnapshot()).put("platform","android").put("version","0.1.1-dev");}catch(Exception ignored){}return o;}
}
